function setVoiceStatus(message,show=true){voiceStatusText.textContent=message;voiceStatus.hidden=!show;}
function cleanTextForSpeech(text){return String(text||'').replace(/```[\s\S]*?```/g,' blok kode ').replace(/`([^`]+)`/g,'$1').replace(/!\[[^\]]*\]\([^)]*\)/g,' gambar ').replace(/\[([^\]]+)\]\([^)]*\)/g,'$1').replace(/[#*_~>|]/g,' ').replace(/https?:\/\/\S+/g,' tautan ').replace(/\s+/g,' ').trim().slice(0,4500);}
function stopVoiceSpeech(){try{if('speechSynthesis' in window)window.speechSynthesis.cancel()}catch{}voiceIsSpeaking=false;}
function speakVoiceReply(text){
  if(!voiceActive)return;
  if(!('speechSynthesis' in window)||typeof SpeechSynthesisUtterance==='undefined'){setVoiceStatus('Browser ini tidak mendukung suara balasan. Coba Chrome atau Edge terbaru.');return;}
  const spoken=cleanTextForSpeech(text);
  if(!spoken){setVoiceStatus('Jawaban tidak berisi teks yang bisa dibacakan.');return;}
  try{
    if(voiceRestartTimer)clearTimeout(voiceRestartTimer);
    // Hentikan sementara pengenalan suara supaya mikrofon tidak menangkap suara JAFN sendiri.
    try{voiceRecognition?.stop()}catch{}
    window.speechSynthesis.cancel();
    const utterance=new SpeechSynthesisUtterance(spoken);
    const voicePrefs=readCompanionSettings();utterance.lang=voicePrefs.voiceLanguage==='auto'?'id-ID':voicePrefs.voiceLanguage;utterance.rate=voicePrefs.voiceRate;utterance.pitch=voicePrefs.voicePitch;
    const voices=window.speechSynthesis.getVoices();
    const chosen=voices.find(v=>v.name===voicePrefs.voiceName);const matching=voices.find(v=>v.lang.toLowerCase()===utterance.lang.toLowerCase())||voices.find(v=>v.lang.toLowerCase().startsWith(utterance.lang.split('-')[0].toLowerCase()));const idVoice=chosen||(voicePrefs.voiceLanguage==='auto'?(voices.find(v=>/^id(-|_)?/i.test(v.lang))||voices.find(v=>/indonesia/i.test(v.name))):matching);
    if(idVoice)utterance.voice=idVoice;
    voiceIsSpeaking=true;
    setVoiceStatus('JAFN AI sedang berbicara…');
    utterance.onend=()=>{voiceIsSpeaking=false;if(voiceActive){setVoiceStatus('Silakan bicara, JAFN AI mendengarkan…');scheduleVoiceRestart(700)}};
    utterance.onerror=(event)=>{voiceIsSpeaking=false;if(voiceActive){const reason=event?.error;setVoiceStatus(reason==='not-allowed'?'Browser memblokir suara. Klik halaman sekali lalu coba lagi.':'Suara balasan gagal diputar. Pastikan volume perangkat aktif, lalu coba lagi.');scheduleVoiceRestart(700)}};
    window.speechSynthesis.speak(utterance);
    // Beberapa browser Chromium kadang membiarkan antrean TTS dalam keadaan paused.
    if(window.speechSynthesis.paused)window.speechSynthesis.resume();
  }catch(error){voiceIsSpeaking=false;setVoiceStatus('Gagal memulai suara balasan. Coba Chrome atau Edge terbaru.');scheduleVoiceRestart(700);}
}
function scheduleVoiceRestart(delay=400){if(!voiceActive||!voiceRecognition||voiceIsSpeaking||busy)return;if(voiceRestartTimer)clearTimeout(voiceRestartTimer);voiceRestartTimer=setTimeout(()=>{if(!voiceActive||voiceIsSpeaking||busy||!voiceRecognition)return;try{voiceRecognition.start()}catch{ /* Recognition mungkin masih aktif; event onend akan mencoba lagi. */ }},delay)}
function stopVoiceChat(){voiceActive=false;if(voiceRestartTimer)clearTimeout(voiceRestartTimer);try{voiceRecognition?.stop()}catch{}stopVoiceSpeech();voiceBtn.classList.remove('active');voiceBtn.textContent='🎙️';voiceBtn.title='Mulai Voice Chat';voiceBtn.setAttribute('aria-label','Mulai Voice Chat');setVoiceStatus('Voice Chat dimatikan.',false);statusText.textContent=busy?'Sedang berpikir…':'Siap membantu';}
function startVoiceChat(){if(!SpeechRecognition){setVoiceStatus('Browser ini belum mendukung pengenalan suara. Coba Chrome atau Edge terbaru.');return;}if(!('speechSynthesis' in window)){setVoiceStatus('Browser ini belum mendukung suara balasan. Coba Chrome atau Edge terbaru.');return;}voiceActive=true;voiceBtn.classList.add('active');voiceBtn.textContent='⏹️';voiceBtn.title='Akhiri Voice Chat';voiceBtn.setAttribute('aria-label','Akhiri Voice Chat');setVoiceStatus('Meminta izin mikrofon…');voiceRecognition=new SpeechRecognition();const selectedVoiceLanguage=readCompanionSettings().voiceLanguage;voiceRecognition.lang=selectedVoiceLanguage==='auto'?'id-ID':selectedVoiceLanguage;voiceRecognition.continuous=true;voiceRecognition.interimResults=true;voiceRecognition.maxAlternatives=1;voiceRecognition.onstart=()=>{if(voiceActive&&!voiceIsSpeaking)setVoiceStatus('Silakan bicara, JAFN AI mendengarkan…')};voiceRecognition.onresult=(event)=>{if(!voiceActive||voiceIsSpeaking)return;let finalText='';let interim='';for(let i=event.resultIndex;i<event.results.length;i++){const transcript=event.results[i][0]?.transcript||'';if(event.results[i].isFinal)finalText+=transcript+' ';else interim+=transcript;}if(interim.trim())setVoiceStatus('Mendengar: '+interim.trim());if(finalText.trim()&&!busy){promptEl.value=finalText.trim();resizePrompt();setVoiceStatus('Aku mendengar: '+finalText.trim());sendMessage();}};voiceRecognition.onerror=(event)=>{if(!voiceActive)return;const messages={ 'not-allowed':'Izin mikrofon ditolak. Izinkan mikrofon di pengaturan browser.','no-speech':'Belum terdengar suara. Silakan bicara lagi.','audio-capture':'Mikrofon tidak ditemukan atau sedang dipakai aplikasi lain.','network':'Pengenalan suara memerlukan koneksi internet pada browser ini.'};setVoiceStatus(messages[event.error]||('Voice Chat mengalami kendala: '+event.error));if(event.error==='not-allowed'||event.error==='service-not-allowed')stopVoiceChat();};voiceRecognition.onend=()=>{if(voiceActive&&!voiceIsSpeaking&&!busy)scheduleVoiceRestart(500)};try{voiceRecognition.start()}catch(e){setVoiceStatus('Mikrofon belum siap. Tekan tombol Voice Chat sekali lagi.');}}
