function makeId(){return 'chat_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,8)}
function persistChats(){try{if(localStorage.getItem('jafn_privacy_save_history')==='false'){localStorage.removeItem('ruangai_chats');return;}localStorage.setItem('ruangai_chats',JSON.stringify(chats.slice(0,150)));}catch{}}
