function saveHistory(){if(!currentChatId){currentChatId=makeId();chats.unshift({id:currentChatId,mode:currentMode,title:'Percakapan baru',updated:Date.now(),messages:[]});}const c=chats.find(x=>x.id===currentChatId);if(c){c.mode=currentMode;c.messages=history.slice(-80);c.title=titleFor(history);c.updated=Date.now();}chats.sort((a,b)=>(b.updated||0)-(a.updated||0));persistChats();renderHistoryList();try{if(localStorage.getItem('jafn_privacy_save_history')!=='false')localStorage.setItem(currentMode==='image'?'ruangai_image_history':'ruangai_history',JSON.stringify(history.slice(-40)));}catch{}}
function renderHistoryList(){const list=$('historyList');if(!list)return;list.replaceChildren();const visibleChats=chatsForMode().sort((a,b)=>(b.updated||0)-(a.updated||0));if(!visibleChats.length){const empty=document.createElement('div');empty.className='history-empty';empty.textContent='Belum ada riwayat chat. Mulai percakapan baru!';list.appendChild(empty);return;}for(const c of visibleChats){const row=document.createElement('div');row.className='history-item'+(c.id===currentChatId?' active':'');const open=document.createElement('button');open.className='history-item';open.style.flex='1';open.style.minWidth='0';const t=document.createElement('span');t.className='history-title';t.textContent='💬 '+(c.title||'Percakapan');const meta=document.createElement('small');meta.textContent=new Date(c.updated||Date.now()).toLocaleDateString('id-ID');t.appendChild(meta);open.appendChild(t);open.addEventListener('click',()=>openChat(c.id));const rename=document.createElement('button');rename.className='mini';rename.title='Ganti nama';rename.textContent='✎';rename.onclick=()=>{const v=prompt('Nama percakapan:',c.title||'Percakapan');if(v&&v.trim()){c.title=v.trim().slice(0,80);persistChats();renderHistoryList();}};const del=document.createElement('button');del.className='mini';del.title='Hapus percakapan';del.textContent='🗑';del.onclick=()=>{if(confirm('Hapus percakapan ini?')){chats=chats.filter(x=>x.id!==c.id);if(currentChatId===c.id)startNewChat();else{persistChats();renderHistoryList();}}};row.append(open,rename,del);list.appendChild(row);}}
function openChat(id){const c=chats.find(x=>x.id===id);if(!c||((c.mode||'text')!==currentMode))return;currentChatId=id;history=Array.isArray(c.messages)?c.messages.slice():[];messagesEl.querySelectorAll('.message').forEach(el=>el.remove());$('welcome').classList.toggle('hidden',history.length>0);for(const m of history){if(m.role==='user'||m.role==='assistant')renderMessage(m.content,m.role,m.image||null);} $('historyPanel').classList.add('hidden');renderHistoryList();}
function startNewChat(){if(busy)return;history=[];currentChatId='';messagesEl.querySelectorAll('.message').forEach(el=>el.remove());$('welcome').classList.remove('hidden');timerEl.textContent='';$('historyPanel').classList.add('hidden');promptEl.value='';documentFile=null;documentText='';imageFile=null;$('documentPreview').classList.add('hidden');$('preview').classList.add('hidden');renderHistoryList();}
