const personalizationDefaults={accent:'#8b7cff',userBubble:'#4b43a7',panel:'#111a2b',shape:'soft',fontSize:'15',opacity:'34'};
function readPersonalization(){try{const saved=JSON.parse(localStorage.getItem('ruangai_personalization')||'{}');delete saved.name;delete saved.avatar;return {...personalizationDefaults,...saved}}catch{return {...personalizationDefaults}}}
function shiftHex(hex){try{const n=parseInt(hex.slice(1),16);const r=Math.min(255,((n>>16)&255)+36),g=Math.min(255,((n>>8)&255)+24),b=Math.min(255,(n&255)+50);return '#'+[r,g,b].map(v=>v.toString(16).padStart(2,'0')).join('')}catch{return '#a78bfa'}}
function blendHex(a,b){try{const x=parseInt(a.slice(1),16),y=parseInt(b.slice(1),16);return '#'+[16,8,0].map(s=>Math.round((((x>>s)&255)*.72+((y>>s)&255)*.28)).toString(16).padStart(2,'0')).join('')}catch{return '#202b48'}}
function applyPersonalization(p){root.style.setProperty('--accent',p.accent||personalizationDefaults.accent);root.style.setProperty('--accent2',shiftHex(p.accent||personalizationDefaults.accent));root.style.setProperty('--userbubble',`linear-gradient(135deg,${p.userBubble||personalizationDefaults.userBubble},${shiftHex(p.accent||personalizationDefaults.accent)})`);root.style.setProperty('--panel',`linear-gradient(145deg,${p.panel||personalizationDefaults.panel},${blendHex(p.panel||personalizationDefaults.panel,p.accent||personalizationDefaults.accent)})`);root.style.setProperty('--custom-font-size',(p.fontSize||'15')+'px');root.style.setProperty('--wallpaper-opacity',String(Math.max(5,Math.min(70,Number(p.opacity)||34))/100));const radii={soft:'17px',round:'26px',sharp:'7px'};root.style.setProperty('--custom-bubble-radius',radii[p.shape]||radii.soft);$('opacityValue').textContent=(p.opacity||'34')+'%';}
function fillPersonalizeForm(){const p=readPersonalization();$('customAccent').value=p.accent;$('customUserBubble').value=p.userBubble;$('customPanel').value=p.panel;$('bubbleShape').value=p.shape;$('chatFontSize').value=p.fontSize;$('wallpaperOpacity').value=p.opacity;applyPersonalization(p);}
function getPersonalizeForm(){return {accent:$('customAccent').value,userBubble:$('customUserBubble').value,panel:$('customPanel').value,shape:$('bubbleShape').value,fontSize:$('chatFontSize').value,opacity:$('wallpaperOpacity').value};}
