// Pemeriksa prompt: menggabungkan deteksi typo lokal dan analisis konteks oleh AI.
const typoMap={"akuu":"aku","sayaas":"saya","syya":"saya","gmn":"bagaimana","gimanaaa":"gimana","bagaimna":"bagaimana","bagaiamana":"bagaimana","tolng":"tolong","tolongg":"tolong","bikinn":"bikin","buatt":"buat","dongg":"dong","apaa":"apa","kenapaa":"kenapa","gakkk":"gak","nggakkk":"nggak","dngan":"dengan","denagn":"dengan","adlah":"adalah","adlh":"adalah","karna":"karena","krna":"karena","tidka":"tidak","tidaak":"tidak","tehnik":"teknik","aktifitas":"aktivitas","resiko":"risiko","ijin":"izin"};
const checkBtn=$('checkPromptBtn'),checkBox=$('promptCheckResults');
function escHTML(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function promptTypeClass(type){const t=String(type||'').toLowerCase();if(/typo|ejaan|salah.?ketik|pengulangan|tata.?bahasa/.test(t))return 'typo';if(/ambigu|jelas.?tidak|ambiguous/.test(t))return 'ambiguous';if(/konteks|context_missing|kurang.?info|kurang.?detail|informasi/.test(t))return 'context';return 'ambiguous';}
function promptLegend(){return '<div class="prompt-legend"><span class="red">🔴 Merah: kemungkinan typo</span><span class="yellow">🟡 Kuning: kalimat ambigu</span><span class="green">🟢 Hijau: prompt jelas</span><span class="blue">🔵 Biru: konteks kurang</span></div>';}
async function runPromptCheck(){const raw=promptEl.value;if(!raw.trim()){checkBox.hidden=false;checkBox.innerHTML='Tulis prompt dulu, sahabat! 😊';return;}checkBtn.disabled=true;checkBtn.textContent='⏳ Sedang memeriksa dengan AI…';checkBox.hidden=false;checkBox.innerHTML='<span>🤖 AI sedang menganalisis typo, ambiguitas, kejelasan, dan konteks…</span>';let aiIssues=[];let aiError='';let overall='';try{const res=await fetch('/api/check-prompt',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:raw})});const data=await res.json();if(!res.ok||data.error)throw new Error(data.error||`Pemeriksaan gagal (HTTP ${res.status})`);aiIssues=Array.isArray(data.issues)?data.issues:[];overall=String(data.overall||'');}catch(err){aiError=err.message||'Pemeriksaan AI gagal.';}
const flags=[];const seen=new Set();for(const m of raw.matchAll(/[\p{L}]+/gu)){const word=m[0],lower=word.toLowerCase();if(typoMap[lower])flags.push({text:word,suggestion:typoMap[lower],type:'typo',reason:'Kemungkinan salah ketik',source:'local'});if(lower.length>=3&&seen.has(lower))flags.push({text:word,suggestion:'',type:'ambiguous',reason:'Kata ini muncul lebih dari sekali; periksa apakah pengulangan disengaja',source:'local'});seen.add(lower);}for(const m of raw.matchAll(/\b([\p{L}]{2,})\s+\1\b/giu)){flags.push({text:m[0],suggestion:m[1],type:'typo',reason:'Kata terduplikasi berurutan',source:'local'});}for(const f of aiIssues){if(!flags.some(x=>x.text===f.text&&x.suggestion===f.suggestion))flags.push({...f,source:'ai'});}checkBtn.disabled=false;checkBtn.textContent='✨ Periksa prompt';checkBox.hidden=false;
if(!flags.length){if(aiError){checkBox.innerHTML='<strong style="color:#b45309">⚠️ Pemeriksaan AI tidak tersedia.</strong><div class="prompt-note">'+escHTML(aiError)+'</div><div class="prompt-note">Pemeriksaan lokal tidak menemukan typo umum, tetapi belum bisa memastikan ambiguitas atau konteks.</div>'+promptLegend();return;}checkBox.innerHTML='<strong class="flagged clear">✓ Prompt tampak jelas</strong><div class="prompt-note">AI tidak menemukan masalah utama. Pastikan prompt tetap menyebutkan tujuan, detail penting, dan konteks yang diperlukan. Analisis AI adalah saran, bukan kepastian.</div>'+promptLegend();return;}
checkBox.innerHTML='<strong>🔎 Bagian yang perlu diperiksa:</strong><div style="margin-top:8px;display:flex;gap:6px;flex-wrap:wrap">'+flags.map(f=>'<span class="flagged '+promptTypeClass(f.type)+'" title="'+escHTML(f.reason)+'">'+escHTML(f.text)+' · '+escHTML(promptTypeClass(f.type)==='typo'?'Typo':promptTypeClass(f.type)==='context'?'Konteks kurang':'Ambigu')+'</span>').join('')+'</div>'+promptLegend()+(aiError?'<div class="prompt-note" style="color:#b45309">AI tidak berhasil dipanggil: '+escHTML(aiError)+'. Yang tampil hanya pemeriksaan lokal.</div>':'<div class="prompt-note">Merah menandai kemungkinan typo; kuning menandai bagian ambigu; biru menunjukkan konteks atau detail yang kurang. Hijau berarti tidak ditemukan masalah utama.</div>')+'<div id="promptFixList"></div>';
const fixList=checkBox.querySelector('#promptFixList');flags.filter(f=>f.suggestion&&f.suggestion!==f.text).forEach(f=>{const row=document.createElement('div');row.className='prompt-fix';const label=document.createElement('span');label.textContent=f.text+' → '+f.suggestion;const reason=document.createElement('small');reason.style.color='var(--muted)';reason.textContent=' · '+(f.reason||f.type||'Saran AI');const btn=document.createElement('button');btn.type='button';btn.textContent='Ganti';btn.addEventListener('click',()=>{const idx=promptEl.value.indexOf(f.text);if(idx<0)return;promptEl.value=promptEl.value.slice(0,idx)+f.suggestion+promptEl.value.slice(idx+f.text.length);promptEl.dispatchEvent(new Event('input',{bubbles:true}));runPromptCheck();promptEl.focus();});row.append(label,reason,btn);fixList.appendChild(row);});}
checkBtn.addEventListener('click',runPromptCheck);promptEl.addEventListener('input',()=>{if(!checkBox.hidden)checkBox.hidden=true;});
// Quick Actions: apply a focused operation to the current prompt and send it to Chat AI.
const quickActionInstructions={summarize:text=>`Ringkas isi berikut menjadi poin-poin utama yang mudah dipahami. Pertahankan fakta penting dan jangan menambahkan informasi yang tidak ada.\n\nTeks atau topik:\n${text}`,translate:text=>`Terjemahkan teks berikut ke Bahasa Indonesia yang alami dan akurat. Pertahankan makna, nada, nama, angka, dan format aslinya. Jika teks sudah berbahasa Indonesia, terjemahkan ke Bahasa Inggris.\n\nTeks:\n${text}`,examples:text=>`Berikan 3 contoh konkret dan mudah dipahami tentang topik atau permintaan berikut. Jelaskan singkat tiap contoh dan pastikan contohnya relevan.\n\nTopik atau permintaan:\n${text}`,table:text=>`WAJIB jawab dalam bentuk tabel Markdown yang benar, bukan paragraf. Mulai dengan satu baris header, lalu baris pemisah Markdown seperti |---|---|, lalu isi baris-baris tabel. Gunakan minimal 2 kolom jika masuk akal. Jangan bungkus tabel dalam code fence. Tambahkan penjelasan singkat di luar tabel hanya jika perlu. Pilih kolom relevan, pertahankan informasi penting, dan jangan mengarang data. Jika topik berupa konsep umum, buat tabel perbandingan/ringkasan yang berguna; jangan menolak membuat tabel hanya karena teks singkat.\n\nTeks atau topik:\n${text}`};
document.querySelectorAll('.quick-action-btn').forEach(button=>button.addEventListener('click',()=>{if(busy)return;const raw=promptEl.value.trim();if(!raw){promptEl.focus();promptEl.placeholder='Tulis teks atau topik dulu, lalu pilih aksi cepat…';return;}const action=button.dataset.action;const instruction=quickActionInstructions[action];if(!instruction)return;promptEl.value=instruction(raw);resizePrompt();promptEl.dispatchEvent(new Event('input',{bubbles:true}));sendMessage();}));

// Companion settings: personality, browser voices, focus mode, onboarding, feedback, and resume chat.
const COMPANION_KEY='jafn_companion_settings_v1';
const companionDefaults={personality:'friendly',voiceLanguage:'id-ID',voiceName:'auto',voiceRate:1,voicePitch:1,focusMode:false};
function readCompanionSettings(){try{return {...companionDefaults,...JSON.parse(localStorage.getItem(COMPANION_KEY)||'{}')}}catch{return {...companionDefaults}}}
function saveCompanionSettings(value){const next={...companionDefaults,...value};try{localStorage.setItem(COMPANION_KEY,JSON.stringify(next))}catch{};document.body.classList.toggle('focus-mode',!!next.focusMode);return next}
function populateVoiceChoices(){const select=$('voiceChoice');if(!select)return;const previous=readCompanionSettings().voiceName;select.replaceChildren();const auto=document.createElement('option');auto.value='auto';auto.textContent='Otomatis';select.appendChild(auto);let voices=[];try{voices=window.speechSynthesis?.getVoices?.()||[]}catch{}voices.forEach(v=>{const opt=document.createElement('option');opt.value=v.name;opt.textContent=`${v.name} (${v.lang})`;select.appendChild(opt)});select.value=[...select.options].some(o=>o.value===previous)?previous:'auto';}
function fillCompanionForm(){const c=readCompanionSettings();$('personalitySelect').value=c.personality;$('voiceLanguage').value=c.voiceLanguage;$('voiceRate').value=String(c.voiceRate);$('voicePitch').value=String(c.voicePitch);$('voiceRateValue').textContent=Number(c.voiceRate).toFixed(1)+'×';$('voicePitchValue').textContent=Number(c.voicePitch).toFixed(1);$('focusModeToggle').checked=!!c.focusMode;populateVoiceChoices();$('voiceChoice').value=c.voiceName;document.body.classList.toggle('focus-mode',!!c.focusMode);}
function openCompanion(){fillCompanionForm();renderContinueList();$('companionCenter').hidden=false;}
function renderContinueList(){const el=$('continueList');if(!el)return;el.replaceChildren();const recent=[...chats].sort((a,b)=>(b.updated||0)-(a.updated||0)).slice(0,5);if(!recent.length){const p=document.createElement('p');p.className='companion-help';p.textContent='Belum ada percakapan tersimpan. Setelah mengobrol, percakapan terakhir akan muncul di sini.';el.appendChild(p);return;}recent.forEach(c=>{const b=document.createElement('button');b.type='button';b.className='continue-item';const span=document.createElement('span');const title=document.createElement('b');title.textContent=c.title||'Percakapan';const meta=document.createElement('small');meta.textContent=`Terakhir dibuka: ${new Date(c.updated||Date.now()).toLocaleString('id-ID')} · ${(c.messages||[]).length} pesan`;span.append(title,meta);b.appendChild(span);b.addEventListener('click',()=>{currentMode=c.mode||'text';openChat(c.id);$('companionCenter').hidden=true;});el.appendChild(b);});}
$('companionBtn').addEventListener('click',openCompanion);$('companionClose').addEventListener('click',()=>$('companionCenter').hidden=true);$('companionCenter').addEventListener('click',e=>{if(e.target===$('companionCenter'))$('companionCenter').hidden=true});
$('voiceRate').addEventListener('input',()=>{$('voiceRateValue').textContent=Number($('voiceRate').value).toFixed(1)+'×'});$('voicePitch').addEventListener('input',()=>{$('voicePitchValue').textContent=Number($('voicePitch').value).toFixed(1)});
$('voiceLanguage').addEventListener('change',()=>{const c=readCompanionSettings();c.voiceLanguage=$('voiceLanguage').value;c.voiceName='auto';saveCompanionSettings(c);populateVoiceChoices()});$('voiceChoice').addEventListener('focus',populateVoiceChoices);
$('companionSave').addEventListener('click',()=>{const c=saveCompanionSettings({personality:$('personalitySelect').value,voiceLanguage:$('voiceLanguage').value,voiceName:$('voiceChoice').value,voiceRate:Number($('voiceRate').value),voicePitch:Number($('voicePitch').value),focusMode:$('focusModeToggle').checked});$('companionCenter').hidden=true;statusText.textContent='Preferensi karakter disimpan';setTimeout(()=>{if(!busy)statusText.textContent='Siap membantu'},1400);});
$('companionReset').addEventListener('click',()=>{saveCompanionSettings({...companionDefaults});fillCompanionForm()});$('focusModeToggle').addEventListener('change',()=>{document.body.classList.toggle('focus-mode',$('focusModeToggle').checked)});
if(window.speechSynthesis){window.speechSynthesis.addEventListener?.('voiceschanged',populateVoiceChoices)}
// Feed the selected personality into the server's system prompt without changing chat history.
$('messages').addEventListener('click',e=>{const button=e.target.closest('button[data-feedback]');if(!button)return;const wrap=button.closest('.message-feedback');if(!wrap)return;const action=button.dataset.feedback;const status=wrap.querySelector('.feedback-status');if(action==='improve'){const answer=wrap.dataset.answer||'';promptEl.value='Tolong perbaiki jawaban JAFN AI sebelumnya agar lebih akurat, jelas, dan langsung menjawab pertanyaanku. Pertahankan bagian yang benar dan koreksi kekurangannya.\n\nJawaban sebelumnya:\n'+answer;resizePrompt();$('companionCenter').hidden=true;promptEl.focus();sendMessage();return;}wrap.querySelectorAll('button[data-feedback]').forEach(b=>{if(b!==button)b.classList.remove('selected')});button.classList.add('selected');status.textContent=action==='up'?'Terima kasih atas penilaianmu.':'Terima kasih. Kamu bisa memilih “Perbaiki jawaban”.';try{const key='jafn_response_feedback_v1';const list=JSON.parse(localStorage.getItem(key)||'[]');list.push({rating:action,at:Date.now()});localStorage.setItem(key,JSON.stringify(list.slice(-300)))}catch{}});
const onboardingSteps=[{title:'Kenalan dengan JAFN AI',text:'Aku bisa menjawab pertanyaan, membantu menulis, dan menjelaskan topik dengan bahasa yang mudah dipahami.'},{title:'Kirim gambar atau dokumen',text:'Gunakan tombol + di dekat kolom pesan untuk mengirim gambar, PDF, Word, dan file teks yang didukung.'},{title:'Sesuaikan pengalamanmu',text:'Gunakan 🎭 untuk memilih karakter, mengatur suara, mengaktifkan Focus mode, atau melanjutkan percakapan sebelumnya. Tombol ☰ membuka riwayat chat.'}];let onboardingIndex=0;
function showOnboardingStep(){const step=onboardingSteps[onboardingIndex];$('onboardingTitle').textContent=step.title;$('onboardingText').textContent=step.text;[...$('onboardingDots').children].forEach((d,i)=>d.classList.toggle('active',i===onboardingIndex));$('onboardingNext').textContent=onboardingIndex===onboardingSteps.length-1?'Mulai menggunakan JAFN AI':'Lanjut →';}
function closeOnboarding(){ $('onboardingOverlay').hidden=true;try{localStorage.setItem('jafn_onboarding_done_v1','true')}catch{}}
$('onboardingNext').addEventListener('click',()=>{if(onboardingIndex<onboardingSteps.length-1){onboardingIndex++;showOnboardingStep()}else closeOnboarding()});$('onboardingSkip').addEventListener('click',closeOnboarding);
function initCompanion(){fillCompanionForm();try{if(localStorage.getItem('jafn_onboarding_done_v1')!=='true'){onboardingIndex=0;showOnboardingStep();$('onboardingOverlay').hidden=false}}catch{}}
initCompanion();


